code='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            cells = {(r, c)}
            seen.add((r, c))
            stack = [(r, c)]
            while stack:
                y, x = stack.pop()
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    p = (y+dy, x+dx)
                    if 0 <= p[0] < h and 0 <= p[1] < w and p not in seen and grid[p[0]][p[1]] == color:
                        seen.add(p); cells.add(p); stack.append(p)
            minr = min(y for y, x in cells); maxr = max(y for y, x in cells)
            minc = min(x for y, x in cells); maxc = max(x for y, x in cells)
            zeros = {(y,x) for y in range(minr,maxr+1) for x in range(minc,maxc+1) if (y,x) not in cells}
            outside = {p for p in zeros if p[0] in (minr,maxr) or p[1] in (minc,maxc)}
            todo = list(outside)
            while todo:
                y,x = todo.pop()
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    p=(y+dy,x+dx)
                    if p in zeros and p not in outside:
                        outside.add(p); todo.append(p)
            goes_up = bool(zeros - outside)
            objects.append({'color':color,'cells':cells,'up':goes_up})
    # Move each shape one row at a time toward its assigned edge. Lower objects
    # move first when falling; upper objects move first when rising.
    for _ in range(h * h):
        changed = False
        order = sorted(range(len(objects)), key=lambda i: (min(r for r,c in objects[i]['cells']) if objects[i]['up'] else -max(r for r,c in objects[i]['cells'])))
        for i in order:
            obj=objects[i]; dy=-1 if obj['up'] else 1
            moved={(r+dy,c) for r,c in obj['cells']}
            if any(r<0 or r>=h for r,c in moved):
                continue
            occupied=set().union(*(o['cells'] for j,o in enumerate(objects) if j != i))
            if not moved & occupied:
                obj['cells']=moved; changed=True
        if not changed:
            break
    out=[[0]*w for _ in range(h)]
    for obj in objects:
        for r,c in obj['cells']:
            out[r][c]=obj['color']
    return out
